            updateAlertMessage(value);
        }

        function updateAlertMessage(value) {
            if (value <= 50) {
                alertMessage.text('Chất lượng không khí đạt tiêu chuẩn tốt. Tự do thực hiện các hoạt ngoài trời động ngoài trời.');
                alertMessage.css('color', 'rgb(0, 102, 0)');
            } else if (value <= 100) {
                alertMessage.text('Chất lượng không khí chấp nhận được.Tự do thực hiện các hoạt ngoài trời động ngoài trời.Nhóm người nhạy cảm nên theo dõi các triệu chứng như ho hoặc khó thở, nhưng vẫn có thể hoạt động bên ngoài.');
                alertMessage.css('color', 'rgb(197, 97, 0)');
            } else if (value <= 150) {
                alertMessage.text('Chất lượng không khí không tốt. Những người thấy có triệu chứng đau mắt, ho hoặc đau họng... nên cân nhắc giảm các hoạt động ngoài trời. Đối với học sinh, có thể hoạt động bên ngoài, nhưng nên giảm bớt việc tập thể dục kéo dài.');
                alertMessage.css('color', 'rgb(255, 126, 0)');
            } else if (value <= 200) {
                alertMessage.text('Chất lượng không khí kém. Mọi người nên giảm các hoạt hoạt động mạnh khi ở ngoài trời, tránh tập thể dục kéo dài và nghỉ ngơi nhiều hơn trong nhà.');
