            } else if (value <= 300) {
                alertMessage.text('Chất lượng không khí rất kém. Mọi người hạn chế tối đa các hoạt động ngoài trời và chuyển tất cả các hoạt động vào trong nhà. Nếu cần thiết phải ra ngoài, hãy đeo khẩu trang đạt tiêu chuẩn.');
                alertMessage.css('color', 'rgb(143, 63, 151)');
