        var defaultLng = 105.804817;

        var lat = localStorage.getItem('latitude');
        var lon = localStorage.getItem('longitude');
        if (lat == null || lon == null) {
            callApi(defaultLat, defaultLng);
        } else {
            callApi(lat, lon);
        }
        $(document).on('localstorageChange', function (e, key, value) {
            if (key === 'checkLocal') {
                if (value == 'yes') {
                    var lat = localStorage.getItem('latitude');
