                    }]
                }]
            });
            updateAlertMessage(value);
        }

        function updateAlertMessage(value) {
            if (value <= 50) {
                alertMessage.text('Chất lượng không khí đạt tiêu chuẩn tốt. Tự do thực hiện các hoạt ngoài trời động ngoài trời.');
