        };

        // Sử dụng cấu hình và dữ liệu để hiển thị biểu đồ
        option && myChart.setOption(option);

        // Hàm tạo số random và cập nhật biểu đồ khi tải lại trang
        function updateChart(value) {
            var randomValue = Math.round(Math.random() * 300); // Tạo giá trị AQI từ 0 đến 500
            myChart.setOption({
