                    callApi(lat, lon);
                    $(".child-background-tran").hide();
                    $(".main-cscl").removeClass('opacitybackground1');
                } else {
                    //Nếu người dùng chọn không thì mặc định ở hà nội
                    var lat = 21.028511;
                    var lon = 105.804817;
                    callApi(lat, lon);
                    $(".child-background-tran").show();
                    $(".main-cscl").addClass('opacitybackground1');
                }

            }
        });

        //getCurrentLocation();
        $("#GetViTri").on('click', function () {
            getCurrentLocation();
        });
        function getCurrentLocation() {
            if (navigator.geolocation) {
                navigator.geolocation.getCurrentPosition((position) => {
                    // Send the position data to your server
                    latitude = position.coords.latitude;
                    longitude = position.coords.longitude;
                    // get name of location
                    callApi(latitude, longitude);

                }, showError);
            } else {
                callApi(defaultLat, defaultLng);
            }
        }
        function showError(error) {
            switch (error.code) {
                case error.PERMISSION_DENIED:
                    alert("Người dùng đã từ chối yêu cầu Định vị địa lý.");
                    callApi(defaultLat, defaultLng);
                    break;
                case error.POSITION_UNAVAILABLE:
                    alert("Thông tin vị trí không khả dụng.");
                    callApi(defaultLat, defaultLng);
                    break;
                case error.TIMEOUT:
                    alert("Yêu cầu lấy vị trí đã hết thời gian chờ.");
                    callApi(defaultLat, defaultLng);
                    break;
                //case error.UNKNOWN_ERROR:
                //    alert("Đã xảy ra lỗi không xác định.");
                //    callApi(defaultLat, defaultLng);
                //    break;
            }
        }

        function callApi(lat, lng) {
            console.log(lat);
            console.log(lng);
            function fetchDataFromJson(filePath, callback) {
                $.getJSON(filePath, function (data) {
                    if (typeof callback === 'function') {
                        callback(data);
                    }
                }).fail(function (jqXHR, textStatus, errorThrown) {
                    console.error("Không thể tải file JSON:", textStatus, errorThrown);
                });
            }

            fetchDataFromJson('/SMPT_Publishing_UC/KhaiThacBoTaiNguyenMoiTruong/UCKhaiThac/ChatLuongKhongKhi.js', function (data) {
                const nearestObject = data.reduce((nearest, current) => {
                    const distance = calculateDistance(lat, lng, current.latitude, current.longitude);
                    return distance < nearest.distance ? { object: current, distance } : nearest;
                }, { object: null, distance: Infinity });
                console.log("Object gần nhất:", nearestObject.object);

                var url = `https://envisoft.gov.vn/eos/api_led/call/json/aqi_day?station_id=${nearestObject.object.id}`;
                $.get(url, function (data) {
                    var pm25Value = data.data.aqi_hour['PM-2-5'];
                    if (!isNaN(pm25Value)) {
                        pm25Value = Math.round(parseFloat(pm25Value));
                    }
                    updateChart(pm25Value);
                    var fullCityName = nearestObject.object.location;
                    if (fullCityName != undefined) {
                        updateTime(fullCityName);
                    } else {
                        updateTime(nearestObject.object.station_name);
                    }

                }).fail(function () {
                   /* alert("Đã xảy ra lỗi không xác định.");*/
                });
            });

            function calculateDistance(lat1, lon1, lat2, lon2) {
                const R = 6371; // Bán kính Trái Đất (km)
                const dLat = (lat2 - lat1) * Math.PI / 180;
                const dLon = (lon2 - lon1) * Math.PI / 180;
                const a = Math.sin(dLat / 2) * Math.sin(dLat / 2) +
                    Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) *
                    Math.sin(dLon / 2) * Math.sin(dLon / 2);
                const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
                return R * c; // Khoảng cách tính bằng km
            }
        }
