            series: [
                {
                    name: 'Đề xuất cấp giấy phép môi trường',
                    type: 'line',
                    stack: 'Total',
                    data: data1,
                    lineStyle: {
                        color: 'red'
                    },
                    itemStyle: {
                        color: 'red'
                    }
                },
                {
                    name: 'Đánh giá tác động môi trường',
                    type: 'line',
                    stack: 'Total',
                    data: data2,
                    lineStyle: {
                        color: 'blue'
                    },
                    itemStyle: {
                        color: 'blue'
                    }
                }
            ]
        };


        option && myChart.setOption(option);
    })

    function getLast12Months() {
        const months = [];
        const currentDate = new Date();

        // Lặp qua 12 tháng từ tháng hiện tại trở về trước
        for (let i = 0; i < 12; i++) {
            // Tạo một đối tượng Date cho tháng hiện tại trừ đi i tháng
            const date = new Date(currentDate.getFullYear(), currentDate.getMonth() - i, 1);
            const monthName = date.getMonth();
            const year = date.getFullYear();
            months.unshift(`${monthName}/${year}`); // Thêm vào đầu mảng để tháng gần nhất xuất hiện trước
        }

        return months;
    }
</script> </div><div class="ms-clear"></div></div> </div><div class="ms-PartSpacingVertical"></div> </div><div id="MSOZoneCell_WebPartctl00_ctl36_g_a61956c4_e0b9_4ca9_90d3_c2fa5eb1d22a" class="s4-wpcell-plain ms-webpartzone-cell ms-webpart-cell-vertical-inline-table ms-webpart-cell-vertical ms-fullWidth "> <div class="ms-webpart-chrome ms-webpart-chrome-vertical ms-webpart-chrome-fullWidth "> <div WebPartID="a61956c4-e0b9-4ca9-90d3-c2fa5eb1d22a" HasPers="false" id="WebPartctl00_ctl36_g_a61956c4_e0b9_4ca9_90d3_c2fa5eb1d22a" width="100%" class="ms-WPBody noindex " allowDelete="false" allowExport="false" style=""><div id="ctl00_ctl36_g_a61956c4_e0b9_4ca9_90d3_c2fa5eb1d22a"> <style>
